/*
 * prog19_palindrome_checker.c
 *
 * Re‑implementation of the original binary’s behaviour.
 *
 * Behaviour (identical to the original program):
 *
 * 1. If the program is started without a command‑line argument,
 *    the (empty) argument is treated as a palindrome and the program
 *    prints "PALINDROME".
 *
 * 2. If an argument is supplied and its length (as measured by strlen)
 *    exceeds 1024 characters, the program prints "TOO_LONG".
 *
 * 3. Otherwise the argument is *normalised*:
 *        – all characters that are not alphanumeric are removed,
 *        – letters are converted to lower case,
 *        – digits are kept unchanged.
 *
 *    The normalised string is then tested for being a palindrome.
 *
 * 4. If the normalised string is a palindrome the program prints
 *    "PALINDROME", otherwise it prints "NOT_PALINDROME".
 *
 * The literal strings used match those embedded in the original binary.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT_LEN 1024          /* 0x400 in the original binary */

#define STR_TOO_LONG      "TOO_LONG"
#define STR_PALINDROME    "PALINDROME"
#define STR_NOT_PALINDROME "NOT_PALINDROME"

int main(int argc, char *argv[])
{
    /* -------------------------------------------------------------
     * 1. Argument handling
     * ------------------------------------------------------------- */
    const char *input;
    if (argc <= 1) {
        /* No argument – the original program treats the empty string
         * as a palindrome. */
        puts(STR_PALINDROME);
        return 0;
    }

    input = argv[1];
    size_t len = strlen(input);

    /* -------------------------------------------------------------
     * 2. Length check (original limit is 0x400 == 1024)
     * ------------------------------------------------------------- */
    if (len > MAX_INPUT_LEN) {
        puts(STR_TOO_LONG);
        return 0;
    }

    /* -------------------------------------------------------------
     * 3. Normalisation: keep only alphanumeric characters,
     *    convert letters to lower case.
     * ------------------------------------------------------------- */
    char norm[MAX_INPUT_LEN + 1];   /* +1 for terminating NUL */
    size_t n = 0;

    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (isalnum(c)) {
            norm[n++] = (char)tolower(c);
        }
    }
    norm[n] = '\0';

    /* -------------------------------------------------------------
     * 4. Palindrome test on the normalised string
     * ------------------------------------------------------------- */
    int is_pal = 1;   /* assume true */
    for (size_t i = 0; i < n / 2; ++i) {
        if (norm[i] != norm[n - 1 - i]) {
            is_pal = 0;
            break;
        }
    }

    puts(is_pal ? STR_PALINDROME : STR_NOT_PALINDROME);
    return 0;
}
